 "<b style=\"font-size:24px;color:#7a5bc7\">Reptiles</b><br><span style=\"font-size:20px;color:#102e2d\">Piel con escamas, huevos.</span>": "<b style=\"font-size:24px;color:#7a5bc7\">Reptilien</b><br><span style=\"font-size:20px;color:#102e2d\">Haut mit Schuppen, Eier.</span>",
 "<b style=\"font-size:24px;color:#ad8322\">Anfibios</b><br><span style=\"font-size:20px;color:#102e2d\">Piel fina, de renacuajo a adulto.</span>": "<b style=\"font-size:24px;color:#ad8322\">Amphibien</b><br><span style=\"font-size:20px;color:#102e2d\">Dünne Haut, von der Kaulquappe zum erwachsenen Tier.</span>",
 "<b style=\"font-size:24px;color:#1f948f\">Peces</b><br><span style=\"font-size:20px;color:#102e2d\">Branquias, aletas, viven en agua.</span>": "<b style=\"font-size:24px;color:#1f948f\">Fische</b><br><span style=\"font-size:20px;color:#102e2d\">Kiemen, Flossen, leben im Wasser.</span>",
